package com.example.discussions.security;
import com.example.discussions.repository.UserRepository;import io.jsonwebtoken.JwtException;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter {private final JwtService jwt;private final UserRepository users;public JwtFilter(JwtService jwt,UserRepository users){this.jwt=jwt;this.users=users;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{var h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String name=jwt.subject(h.substring(7));users.findByUsernameIgnoreCase(name).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.username,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.role.name())))));}catch(JwtException ignored){}chain.doFilter(req,res);}}
